import{_ as a,H as n,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"29 | 遗留系统上的Harness驱动开发实践（一）","description":"","frontmatter":{},"headers":[{"level":2,"title":"遗留系统的知识库构建","slug":"遗留系统的知识库构建","link":"#遗留系统的知识库构建","children":[]},{"level":2,"title":"软件架构作为知识库的索引","slug":"软件架构作为知识库的索引","link":"#软件架构作为知识库的索引","children":[{"level":3,"title":"一个例子","slug":"一个例子","link":"#一个例子","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Agent驾驭工程之美/29｜遗留系统上的Harness驱动开发实践（一）.md","filePath":"Agent驾驭工程之美/29｜遗留系统上的Harness驱动开发实践（一）.md","lastUpdated":1795453770000}'),i={name:"Agent驾驭工程之美/29｜遗留系统上的Harness驱动开发实践（一）.md"};function l(t,s,c,o,d,r){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_29-遗留系统上的harness驱动开发实践-一" tabindex="-1">29 | 遗留系统上的Harness驱动开发实践（一） <a class="header-anchor" href="#_29-遗留系统上的harness驱动开发实践-一" aria-label="Permalink to &quot;29 | 遗留系统上的Harness驱动开发实践（一）&quot;">​</a></h1><p>你好，我是徐昊，欢迎继续学习驾驭工程。</p><p>上一讲我们讲了 Agent First Workspace 是如何辅助我编写这门课程的。那么接下来让我们看一个稍微复杂一点的场景：如何针对遗留系统，构造 Agent First Workspace。这一讲我们首先聚焦在如何构造知识库上。</p><h2 id="遗留系统的知识库构建" tabindex="-1">遗留系统的知识库构建 <a class="header-anchor" href="#遗留系统的知识库构建" aria-label="Permalink to &quot;遗留系统的知识库构建&quot;">​</a></h2><p>对于遗留系统，一个常见的误区是，我们总希望能够补全它的业务目标、业务场景、业务规则等等。但是通常对于遗留系统来说，这些信息要么分散在各种不同系统中，要么早就随着人员的更替，烟消云散了。</p><p>因此，在遗留系统上，试图先把业务补全、再让 Agent 开工，这条路几乎走不通。你投入大量时间去追业务信息，追到最后会发现，那些最关键的部分，比如某个字段当初为什么这么设计、某个分支是给哪个历史场景留的、某条规则为什么例外，根本补不全，是常态，不是意外。也正如我们在《AI 时代的软件工程》中讲到的，知识丢失是软件退化为遗留系统的根本原因。</p><p>所以遗留系统的知识库，不能建立在“业务信息完整”这个前提上。这个前提在新项目（GreenField）里有可能成立，在那里你可以从业务目标一路推到代码；但在遗留系统里，它从一开始就不成立。真正还完整地、原封不动地留在你手里的，只有一样东西：代码本身。业务可能烟消云散，代码不会；业务规则可能被人带走，代码里当年写下的每一个判断，都还躺在原地。</p><p>所以，为遗留系统构造知识库，大部分时候只能靠 Agent 直接读代码，把系统实际在做什么挖出来。但是我们都知道，通过 AI 阅读软件代码，只能了解“系统在做什么”（What SystemDoes），但是对于“系统是什么”（What System Is）只能有一定的推测，而不一定能完全理解。</p><p>比如，在挖掘过程中，Agent 会发现一堆它看不懂的东西：某个奇怪的判断、某段没人解释的补丁、某个和业务对不上的逻辑。这些“看不懂”，恰恰就是当年那些烟消云散的业务信息在代码里留下的影子。</p><p>这时候，我们可以通过上下文补充，或者拿 AI 给的一个问题列表，再去寻找答案。因此，我们需要把业务背景当作帮助 AI 理解代码的补充说明，而不是知识库的地基。这才能解决，如何开始利用 Agent 处理遗留系统的问题，而不是陷入无尽的等待，而迟迟无法开工。</p><h2 id="软件架构作为知识库的索引" tabindex="-1">软件架构作为知识库的索引 <a class="header-anchor" href="#软件架构作为知识库的索引" aria-label="Permalink to &quot;软件架构作为知识库的索引&quot;">​</a></h2><p>当我们围绕代码库构建知识库的时候，就会面临 Agent 的上下文窗口限制。哪怕对于小型项目，我们把所有代码都塞入上下文中，也会因为上下文焦虑造成注意力偏移等问题。</p><p>前面讲上下文焦虑的时候，我们给过一套压缩的做法：筛选、分层、按需加载，压缩时保留关键决策及理由，装不下的再用 subagent 切分。现在把这套做法用到遗留系统的知识库上，答案就显而易见了，面对代码库，压缩的最好方式，就是按架构来压。</p><p>架构天然就是代码的一份压缩。它把几十万行代码筛掉实现细节，按模块分层，压缩成“系统分成几块、每块负责什么、块之间怎么连”的骨架。这份骨架信息密度最高、也最稳定，正是压缩该留下的东西。而“按需加载”在这里就是，索引里只留骨架，Agent 需要细节时，再回原代码读对应那一块。骨架常驻，细节按需读入。</p><p>明确了方向，在开始动手之前，还需要注意一点，我们应该从 Agent 的角度构造知识库，而不是从人的习惯入手。</p><p>以使用微服务架构模式的系统来举例。作为程序员我们关注的软件架构，往往是从每个服务是如何实现的来考虑。它是多层的 clean code 风格呢？还是 smart domain 风格呢？然后我们就希望 Agent 也要按照这样的方式去理解我们的系统。</p><p>但是我们需要知道的是，软件工程这么多年总结的最佳实践，是为了配合人的认知能力。这时候，我们不妨把人想成一个上下文空间极度有限的大模型，因为我们的上下文有限，所以我们只能按照分层、或者通过高度提炼的领域模型（domain model）来理解软件系统。但是大模型没有这个限制，它有足够大的上下文，一个微服务的代码它一口气就能读完，内部那几层它随时能回原代码里重新读，根本不用压进索引。</p><p>所以此时对于大模型而言，更重要的是服务之间的边界与交互：这个功能到底归哪个服务，两个服务怎么通信，数据归谁，改一处会波及到哪。这些就是代码里最该保留的“决策理由”，它们散落在多个服务之间，靠读单个服务是拼不出来的。</p><p>所以对一个微服务系统而言，我们应该从服务的边界上入手，构造知识库，而不是在服务内部。索引里留的是每个服务的职责、服务之间的调用关系、数据的所有权；服务内部的分层，交给 Agent 自己去读原代码（当然我们也可以提供一种更为简单的表现形式，以降低词元的用量，这个先按下不表，下节课揭晓）。压缩要压掉 Agent 能随时重新获取的，留住 Agent 拿不到的。补 Agent 的短板，不重复 Agent 的长处。</p><p>这里我展示一下我的做法，也是 Agent First Workspace 要叫 Workspace 的原因。</p><h3 id="一个例子" tabindex="-1">一个例子 <a class="header-anchor" href="#一个例子" aria-label="Permalink to &quot;一个例子&quot;">​</a></h3><p>首先，让我们先构造一下目录结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/                       ← Agent First Workspace</span></span>
<span class="line"><span>├── AGENTS.md                    ← 入口：地图、约定、意图</span></span>
<span class="line"><span>├── skills/                      ← Skills</span></span>
<span class="line"><span>├── checkout/                    ← 由 agent 托管的工作区</span></span>
<span class="line"><span>└── wiki/                        ← 知识库</span></span>
<span class="line"><span>然后我们需要做的是，构造一个 repository.md 的列表，其中包含当前应用中所有的</span></span></code></pre></div><p>repo。</p><p>比如，可能是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- git@github.com:org/service-a.git</span></span>
<span class="line"><span>- git@github.com:org/service-b.git</span></span>
<span class="line"><span>- git@github.com:org/service-c.git</span></span></code></pre></div><p>我们选择在上面三个 repo 之外来构建一个独立的 repo，把它作为我们的 Agent FirstWorkspace。这是因为我们要提取的知识，不独属于某一个 repo，而是这些 repo 组合在一起，描述它们关系的知识。使用 Agent First Workspace 的时候，我们不去处理任何一个具体</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的 repo，而是完全交由 Agent 全权负责，包括什么时候需要 clone 仓库，什么时候需要更新</span></span></code></pre></div><p>仓库中的内容。</p><p>那么第一步，我们就要根据 repo 列表，给出一个初始地图，也就是系统中一共包含几个repo，它们的主要功能是什么。这可以通过一个简单的 skill 实现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name: repo-index</span></span>
<span class="line"><span>description: 根据 repository.md 的仓库列表，创建或更新知识库的 index</span></span></code></pre></div><ul><li>目标</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读 repository.md，产出 wiki/index.md，回答两个问题：系统一共包含几个 repo，每个 repo 大致是</span></span></code></pre></div><ul><li>步骤</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 读 repository.md，拿到全部 repo 的 git 地址。</span></span>
<span class="line"><span>2. 逐个 clone 到 checkout/ 下；已 clone 过的先 git pull 更新到最新。</span></span>
<span class="line"><span>3. 对每个 repo 只扫表层，不深入：</span></span>
<span class="line"><span>  - 读 README、包名、构建文件（package.json / pom.xml / go.mod / Cargo.toml 等）</span></span>
<span class="line"><span>  - 看顶层目录结构，找出主要模块和入口</span></span>
<span class="line"><span>  - 确认语言和框架</span></span>
<span class="line"><span>4. 综合这些信号，给每个 repo 写一句话&quot;主要功能&quot;。</span></span>
<span class="line"><span>5. 写成 wiki/index.md：</span></span>
<span class="line"><span>| repo      | 主要功能 | 语言/框架 | 关键入口 |</span></span>
<span class="line"><span>|-----------|----------|-----------|----------|</span></span>
<span class="line"><span>| service-a | …        | …         | …        |</span></span></code></pre></div><ul><li>注意</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 这是初始地图，只求&quot;有几个、各自大致做什么&quot;，不求精确。服务之间怎么连、边界在哪，留给下一步的 i</span></span>
<span class="line"><span>- README 只当线索，别全信。主要功能以代码结构和入口为准；README 说的和代码对不上，以代码为准。</span></span>
<span class="line"><span>- clone 出来的代码全部放在 checkout/ 下，只读，不改任何一个被 clone 的 repo。</span></span></code></pre></div><p>接下来我们给出针对每一个仓库的具体分析。如果仍然以微服务系统为例，我一般会从两个关键知识入手：service 提供的 API contract，以及 service 消费的 API contract。也就是说，这个服务提供了哪些 API，他还调用了哪些 API。这样的分析当然也可以交给 skill 来完成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name: api-contracts</span></span>
<span class="line"><span>description: 针对每个服务，提取它提供的 API contract 和它消费的 API contract，分别写成 ap</span></span></code></pre></div><ul><li>目标</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读 wiki/index.md，对每个服务产出两个文件：wiki/{repo}/api.spec.md 记录它提供的 API，wiki</span></span></code></pre></div><ul><li>步骤</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 读 wiki/index.md，拿到全部服务清单。</span></span>
<span class="line"><span>2. 对每个服务，在 checkout/ 下定位代码（已 clone 的先 git pull）。</span></span>
<span class="line"><span>3. 提取&quot;提供的 API&quot;，写成 wiki/{repo}/api.spec.md：</span></span>
<span class="line"><span>  - 扫描路由定义、控制器、接口声明：HTTP 路由注解、express/FastAPI/Spring 的路由、gRPC 的</span></span>
<span class="line"><span>  - 每个 API 记下：路径/方法、一句话用途。</span></span>
<span class="line"><span>| 路径/方法 | 用途 |</span></span>
<span class="line"><span>4. 提取&quot;消费的 API&quot;，写成 wiki/{repo}/api.contract.md：</span></span>
<span class="line"><span>  - 扫描出站调用：指向其它服务的内网 HTTP client、gRPC stub、消息 producer、import 其它服</span></span>
<span class="line"><span>  - 每个依赖记下：调的是哪个服务、哪些路径/方法、用来干什么。</span></span>
<span class="line"><span>| 目标服务 | 路径/方法 | 用途 |</span></span></code></pre></div><ul><li>验证</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读 wiki/index.md，逐个 repo 核对 wiki/{repo}/ 下两个文件都存在且非空：api.spec.md 和 ap</span></span></code></pre></div><ul><li>注意</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 只记&quot;跨服务&quot;的边界，服务内部模块之间的调用不记。</span></span>
<span class="line"><span>- 消费的 API 里，认不出的目标服务照实记下，标成&quot;待确认&quot;，不要猜。</span></span>
<span class="line"><span>- 这一步不写业务含义，只记接口本身。业务含义留给后面的业务注释。</span></span>
<span class="line"><span>- 把所有服务的api.contract.md 拼起来，就是服务之间的调用关系图，也就是这个系统的边界地图。</span></span></code></pre></div><p>当然这是一个非常简化的版本，因为不同的技术栈有不同的 api 调用方式和管理，有的时候需要在其中给定一些惯例和样本。</p><p>有了这两个 skill 之后，我们就可以开始构建知识库了。此时你会发现，Agent 可以自己下载对应的 repo，然后根据 repo 中的内容生成我们需要的知识库。在实际工作中，我通常需要花费35-40 分钟，才能完成每天的知识升级，毕竟我的项目里有 78 个 repo。这个效率还算可以。</p><p>有了知识的雏形之后，我往往希望绘制一张服务地图（service map），也就是根据服务直接的调用关系，使用 mermaid 绘制服务之间的依赖关系：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name: service-map</span></span>
<span class="line"><span>description: 根据所有服务的 api.contract.md 和 api.spec.md，把每个消费的 API 匹配到提供它</span></span></code></pre></div><ul><li>目标</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读所有 wiki/{repo}/api.contract.md 和 api.spec.md，把&quot;谁消费了哪个 API、这个 API 由谁提</span></span></code></pre></div><ul><li>步骤</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 遍历 wiki/ 下所有 repo 目录，收集每个服务的 api.contract.md 和 api.spec.md。</span></span>
<span class="line"><span>2. 从所有 api.spec.md 汇总一张&quot;API → 提供方&quot;对照表：每个路径/方法，由哪个服务提供。</span></span>
<span class="line"><span>3. 从每个 api.contract.md 抽出它消费的 API（路径/方法），查对照表找到提供方，得到一条边：消费</span></span>
<span class="line"><span>4. 用 mermaid 画出，每条边标上被调用的 API：</span></span>
<span class="line"><span>mermaid</span></span>
<span class="line"><span>flowchart LR</span></span>
<span class="line"><span>   service-a --&gt;|GET /orders| service-b</span></span>
<span class="line"><span>   service-a --&gt;|POST /payments| service-c</span></span>
<span class="line"><span>   service-b --&gt;|GET /users| service-c</span></span>
<span class="line"><span>5. 写成 wiki/service-map.md。</span></span></code></pre></div><ul><li>注意</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 方向别画反：消费方指向提供方，边上标的是被调用的那个 API。</span></span>
<span class="line"><span>- 对照表里查不到提供方的 API（外部系统或还没生成的 spec），照实画进去，提供方标成&quot;待确认&quot;，用虚线</span></span>
<span class="line"><span>- 同一个 API 被多个服务提供（不同版本），照实画多条边，别合并。</span></span>
<span class="line"><span>两个改动都落进去了：每条边现在是 service-a --&gt;|GET /orders| service-b，API 标在箭头上；而</span></span></code></pre></div><p>在构建了知识库之后，我们就可以围绕知识库，让 Agent 更有效地在多个 repo 之间完成复杂的任务了，这个我们下节再讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>遗留系统的知识库不能建立在“业务信息完整”这个前提上：业务目标、场景、规则要么分散在不同系统，要么随人员更替烟消云散，知识丢失正是软件退化为遗留系统的根本原因。代码是唯一还完整留在手里的东西，所以知识库要锚在代码上，业务背景只当补充说明，不能当地基。</p></li><li><p>面对代码库，上下文压缩的最好方式是按架构压：架构是代码筛掉实现细节、按模块分层后的骨架，信息密度最高、也最稳定。骨架常驻索引，细节按需回原代码读。</p></li><li><p>构造知识库要从 Agent 的角度、而不是从人的习惯入手：软件工程的分层和领域模型，是为配合人有限的认知能力设计的；Agent 上下文足够大，一个 microservice 一口气能读完，它的短板在服务边界。所以索引画在边界上（职责、调用关系、数据所有权），内部分层交给 Agent 自己去读。压缩要压掉 Agent 能随时重新获取的，留住它拿不到的。</p></li><li><p>一个可复制的做法：独立的 workspace（AGENTS.md + skills/ + checkout/ + wiki/），用三个 skill 层层递进——repo-index 出初始地图，api-contracts 给每个服务写 spec（提供的API）和 contract（消费的 API），service-map 把两者对照、反查出调用关系、画成带 API标注的 mermaid 依赖图。</p></li><li><p>这份知识库是后续所有工作的地基：建好之后，Agent 才能围绕它在多个 repo 之间高效完成复杂任务，而不是每次从头读代码。</p></li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>课程用微服务架构作为知识索引。如果面对的是一个没有清晰服务边界的“大泥球”单体系统，你会用什么来组织知识？</p><p>期待你在留言区积极发言，踊跃分享。也欢迎你把课程分享给有需要的朋友。</p>`,63)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
